#!/usr/bin/env node
// Builds the static site from src/ and site.config.json into the repo root,
// along with sitemap.xml and robots.txt.
//
//   node scripts/build.mjs          write pages
//   node scripts/build.mjs --check  exit 1 if any committed file is out of date
//
// Templates support:
//   {{> partial}}         include src/partials/partial.html
//   {{path.to.value}}     value from site.config.json (HTML-escaped)
//   {{@helper}}           HTML generated by a helper below
// Each page starts with <!--page {"title": "...", "description": "..."} -->,
// optionally with "fullTitle" to set the whole <title>.

import { readFileSync, writeFileSync, readdirSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const config = JSON.parse(readFileSync(join(root, "site.config.json"), "utf8"));
const check = process.argv.includes("--check");
const siteUrl = `https://${config.brand.domain}`;
const ogImageAlt = `The ${config.brand.name} ibis: a red zero forms the body of a black-headed ibis, beside the words ${config.brand.competitionName} ${config.brand.year}.`;

const esc = (s) =>
  String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

function lookup(path, scope) {
  const value = path.split(".").reduce((obj, key) => (obj == null ? undefined : obj[key]), scope);
  if (value === undefined) throw new Error(`Unknown template value: {{${path}}}`);
  return value;
}

const NAV = [
  { href: "/competition/", label: "Competition" },
  { href: "/programs/", label: "Programs" },
  { href: "/toolkit/", label: "Toolkit" },
  { href: "/about/", label: "About" },
  { href: "/get-involved/", label: "Get involved" },
];

// A small ibis used as the logo, the walker and the flock.
const useIbis = (cls = "") => `<svg class="mini-ibis ${cls}" viewBox="0 0 64 56" aria-hidden="true" focusable="false"><use href="#ibis"/></svg>`;

// The walker is drawn inline (not <use>) so its legs can be animated.
const walkerSvg = `<svg viewBox="0 0 64 56" focusable="false">
    <g transform="scale(.1)">
      <path d="M450 240 C522 236 584 286 604 372 C566 324 514 300 454 292 Z M458 268 C520 280 566 330 574 414 C542 362 500 336 452 322 Z M446 298 C500 318 532 368 528 440 C506 386 478 360 438 346 Z" fill="currentColor"/>
      <path class="leg-a" d="M326 398 L318 458 L328 520 L292 528" fill="none" stroke="currentColor" stroke-width="19" stroke-linecap="round" stroke-linejoin="round"/><path class="leg-b" d="M392 396 L402 456 L394 518 L358 526" fill="none" stroke="currentColor" stroke-width="19" stroke-linecap="round" stroke-linejoin="round"/>
      <path d="M214 272 C186 228 178 172 184 116 L218 116 C214 168 224 214 258 250 Z" fill="currentColor"/><ellipse cx="360" cy="300" rx="148" ry="102" fill="var(--ibis-fill, #fff)" stroke="var(--ibis-ring, #E1251B)" stroke-width="52"/>
      <ellipse cx="199" cy="102" rx="33" ry="28" fill="currentColor"/><circle cx="208" cy="96" r="7.5" fill="var(--ibis-fill, #fff)"/>
      <path d="M178 84 C124 96 84 154 62 262 C60 267 54 266 55 260 C72 152 114 106 180 114 Z" fill="currentColor"/>
    </g>
</svg>`;
const walker = `<div class="route-track" aria-hidden="true"><div class="walker">${walkerSvg}</div></div>`;

// The stages as a row of columns, each led by its numeral. An ibis walks the
// route as you scroll, and ten ibises (the ten finalist teams) wait at the Final.
function routeList(cls) {
  const numeral = (s) => (s.kind === "gate" ? "Schools" : s.kind === "final" ? "Final" : s.key);
  return `${walker}<ol class="${cls}">${config.stages
    .map(
      (s) => `
      <li class="route-${s.kind}">
        <span class="numeral" aria-hidden="true">${esc(numeral(s))}</span>
        <p class="when">${esc(s.dates)}</p>
        <p class="who">${esc(s.who)}</p>
        <h3>${s.kind === "mile" || s.kind === "check" ? `<span class="vh">${esc(s.label)}: </span>` : ""}${esc(s.name)}${s.kind === "final" ? `, ${esc(config.final.venue)}` : ""}</h3>
        <p class="summary">${esc(s.summary)}</p>
        ${s.submit.length ? `<ul class="submit">${s.submit.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>` : ""}
        ${s.kind === "final" ? `<span class="flock" role="img" aria-label="Ten finalist teams">${useIbis().repeat(10)}</span>` : ""}
      </li>`
    )
    .join("")}
    </ol>`;
}

// The route as a deck of full-screen posters. Each one sticks to the top of the
// screen and the next slides over it. Each poster prints its own progress track;
// with JavaScript, one shared track (the HUD) stays still over the deck instead,
// and the ibis walks along it as you scroll.
function routeStory() {
  const big = (s) => (s.kind === "gate" ? "Schools" : s.kind === "final" ? "Final" : s.key);
  const stops = config.stages;
  return `<div class="story">${stops
    .map((s, i) => {
      const track = stops
        .map(
          (t, j) =>
            `<li class="${j < i ? "done" : j === i ? "here" : ""}"><span class="long">${esc(t.label)}</span><span class="short">${esc(t.kind === "gate" ? "N" : t.kind === "final" ? "F" : t.key)}</span>${j === i && s.kind !== "final" ? useIbis("stop-ibis") : ""}</li>`
        )
        .join("");
      return `
    <article class="stage-screen stage-${s.kind} stage-${esc(s.key.toLowerCase())}" aria-labelledby="stage-${esc(s.key.toLowerCase())}">
      <div class="wrap stage-grid">
        <p class="stage-big${s.key.length > 1 || isNaN(+s.key) ? " stage-word" : ""}" aria-hidden="true">${esc(big(s))}</p>
        <div class="stage-copy">
          <p class="stage-label">${esc(s.label)}, ${esc(s.dates)}</p>
          <h3 id="stage-${esc(s.key.toLowerCase())}">${esc(s.name)}${s.kind === "final" ? `, ${esc(config.final.venue)}` : ""}</h3>
          <p class="stage-who">${esc(s.who)}</p>
          <p class="stage-summary">${esc(s.summary)}</p>
          ${s.submit.length ? `<ul class="stage-submit">${s.submit.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>` : ""}
          ${s.kind === "final" ? `<span class="flock stage-flock" role="img" aria-label="Ten finalist teams">${useIbis().repeat(10)}</span>` : ""}
        </div>
        <ol class="stage-track" aria-hidden="true">${track}</ol>
      </div>
    </article>`;
    })
    .join("")}
    <div class="story-hud" aria-hidden="true" hidden>
      <div class="hud-line"><i class="hud-fill"></i></div>
      <ol class="hud-stops">${stops.map((t) => `<li><span class="long">${esc(t.label)}</span><span class="short">${esc(t.kind === "gate" ? "N" : t.kind === "final" ? "F" : t.key)}</span></li>`).join("")}</ol>
      <div class="hud-walker">${walkerSvg}</div>
    </div>
  </div>`;
}

const helpers = {
  nav: (page) =>
    NAV.map(
      (n) =>
        `<li><a href="${n.href}"${page.url.startsWith(n.href) ? ' aria-current="page"' : ""}>${esc(n.label)}</a></li>`
    ).join(""),

  route: () => routeList("route"),
  routeCompact: () => routeList("route route-compact"),
  routeStory,

  // Eight million tags: 160 dots of 50,000, losing value from left to right.
  tagField: () => {
    const cols = 20, rows = 8, dots = [];
    for (let r = 0; r < rows; r++)
      for (let c = 0; c < cols; c++)
        dots.push(`<circle cx="${6 + c * 12}" cy="${6 + r * 12}" r="3.4" opacity="${(1 - c * 0.034).toFixed(2)}"/>`);
    return `<svg class="tag-field" viewBox="0 0 240 96" role="img" aria-label="160 dots, each standing for 50,000 unsold tags, fading from left to right"><g fill="currentColor">${dots.join("")}</g></svg>`;
  },

  criteria: () =>
    `<dl class="criteria">${config.criteria
      .map((c) => `<div><dt>${esc(c.name)}</dt><dd>${esc(c.question)}</dd></div>`)
      .join("")}</dl>`,

  // Each stage is one bar split by its weights; the table underneath is for screen readers.
  weights: () => `
    <div class="bars" aria-hidden="true">${config.weights
      .map(
        (w) =>
          `<div class="bar-row"><b>${esc(w.stage)}</b><div class="bar">${w.values
            .map((v, i) => `<span class="c${i}" style="flex-basis:${v}%">${v}</span>`)
            .join("")}</div></div>`
      )
      .join("")}
    </div>
    <ul class="legend" aria-hidden="true">${config.criteria.map((c, i) => `<li><i class="c${i}"></i>${esc(c.short)}</li>`).join("")}</ul>
    <div class="vh"><table>
      <caption>Weighting of each criterion by stage, in percent. Mile 0 is auto-marked and not weighted.</caption>
      <thead><tr><th scope="col">Stage</th>${config.criteria.map((c) => `<th scope="col">${esc(c.short)}</th>`).join("")}</tr></thead>
      <tbody>${config.weights
        .map((w) => `<tr><th scope="row">${esc(w.stage)}</th>${w.values.map((v) => `<td>${v}%</td>`).join("")}</tr>`)
        .join("")}</tbody>
    </table></div>
    <p class="small muted">Weights in percent for each stage. Mile 0 is auto-marked and not weighted.</p>`,

  // Only partners whose logo use has been approved in writing appear publicly.
  partnerBar: () => {
    const shown = config.partners.filter((p) => p.logoApproved);
    if (!shown.length) return "";
    return `
    <section class="section" aria-labelledby="partners-h">
      <div class="wrap"><div class="grid">
        <div class="section-title"><h2 id="partners-h">Supported by</h2></div>
        <div class="section-body"><ul class="partner-list">${shown
          .map(
            (p) =>
              `<li>${p.logo ? `<img src="${esc(p.logo)}" alt="${esc(p.name)}" loading="lazy">` : `<span class="partner-name">${esc(p.name)}</span>`}<span class="small muted">${esc(p.role)}</span></li>`
          )
          .join("")}</ul></div>
      </div></div>
    </section>`;
  },

  // Students are only named once they have agreed to it.
  team: () => {
    const shown = config.team.filter((t) => t.consent);
    if (!shown.length) return `<p class="muted">Team profiles are coming soon.</p>`;
    return `<ul class="team">${shown
      .map((t) => `<li><b>${esc(t.name)}</b><span>${esc(t.role)}</span><small>${esc(t.school)}</small></li>`)
      .join("")}</ul>`;
  },

  instagram: () =>
    config.brand.instagram
      ? `<li><a href="https://instagram.com/${esc(config.brand.instagram)}" rel="noopener">Instagram</a></li>`
      : "",

  // The rendered page body, for the layout partial.
  content: (page) => page.body,

  // Canonical URL, social cards and structured data. Only the 404 page is kept out of search.
  seo: (page) => {
    const { brand, final, dates } = config;
    const url = siteUrl + page.url;
    const image = `${siteUrl}/assets/img/og-image.png`;
    const tags = [
      page.slug === "404"
        ? `<meta name="robots" content="noindex">`
        : `<link rel="canonical" href="${esc(url)}">`,
      `<meta property="og:site_name" content="${esc(brand.name)}">`,
      `<meta property="og:locale" content="en_AU">`,
      `<meta property="og:url" content="${esc(url)}">`,
      `<meta property="og:image" content="${image}">`,
      `<meta property="og:image:width" content="1200">`,
      `<meta property="og:image:height" content="630">`,
      `<meta property="og:image:alt" content="${esc(ogImageAlt)}">`,
      `<meta name="twitter:card" content="summary_large_image">`,
    ];
    // Proves to Google Search Console that we own the site (Settings → Ownership verification → HTML tag).
    if (brand.googleSiteVerification && page.slug === "index")
      tags.push(`<meta name="google-site-verification" content="${esc(brand.googleSiteVerification)}">`);

    const org = {
      "@type": "Organization",
      "@id": `${siteUrl}/#org`,
      name: brand.name,
      url: `${siteUrl}/`,
      logo: `${siteUrl}/assets/img/apple-touch-icon.png`,
      email: brand.email,
      description: `A student-led initiative bringing business and finance education to NSW secondary students, and the organiser of the ${brand.competitionName}.`,
      areaServed: "New South Wales, Australia",
      alternateName: [brand.competitionName, brand.competitionShort],
      ...(brand.instagram ? { sameAs: [`https://instagram.com/${brand.instagram}`] } : {}),
    };
    // Tells Google which name to show for the site, and the other names people search for.
    const site = {
      "@type": "WebSite",
      "@id": `${siteUrl}/#site`,
      name: brand.name,
      alternateName: [brand.competitionName, brand.competitionShort],
      url: `${siteUrl}/`,
      publisher: { "@id": `${siteUrl}/#org` },
    };
    const graph = page.slug === "index" ? [org, site] : [org];
    if (page.slug === "competition") {
      graph.push({
        "@type": "Event",
        name: `${brand.competitionName} ${brand.year}`,
        alternateName: `${brand.competitionShort} ${brand.year}`,
        description: page.description,
        url,
        image,
        startDate: dates.mile0OpensISO,
        endDate: final.dateISO,
        eventStatus: "https://schema.org/EventScheduled",
        eventAttendanceMode: "https://schema.org/MixedEventAttendanceMode",
        location: [
          { "@type": "VirtualLocation", url },
          {
            "@type": "Place",
            name: final.venue,
            address: {
              "@type": "PostalAddress",
              streetAddress: final.address.street,
              addressLocality: final.address.locality,
              addressRegion: final.address.region,
              postalCode: final.address.postcode,
              addressCountry: final.address.country,
            },
          },
        ],
        isAccessibleForFree: true,
        offers: {
          "@type": "Offer",
          price: 0,
          priceCurrency: "AUD",
          availability: "https://schema.org/InStock",
          validThrough: dates.registrationClosesISO,
          url: `${siteUrl}/get-involved/`,
        },
        audience: { "@type": "EducationalAudience", educationalRole: "student", audienceType: "NSW secondary school students" },
        organizer: { "@id": `${siteUrl}/#org` },
      });
    }
    // "<" is escaped so the JSON can never close the script tag.
    const json = JSON.stringify({ "@context": "https://schema.org", "@graph": graph }).replace(/</g, "\\u003c");
    return `${tags.join("\n")}\n<script type="application/ld+json">${json}</script>`;
  },
};

function render(template, page, depth = 0) {
  if (depth > 5) throw new Error("Partials nested too deeply");
  return template
    .replace(/\{\{>\s*([\w-]+)\s*\}\}/g, (_, name) =>
      render(readFileSync(join(root, "src/partials", `${name}.html`), "utf8"), page, depth + 1)
    )
    .replace(/\{\{@(\w+)\}\}/g, (_, name) => {
      if (!helpers[name]) throw new Error(`Unknown helper: {{@${name}}}`);
      return helpers[name](page);
    })
    .replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, path) => esc(lookup(path, { ...config, page })));
}

// Every generated file, keyed by its path from the repo root.
const outputs = new Map();
const indexed = [];

const pagesDir = join(root, "src/pages");
for (const file of readdirSync(pagesDir).filter((f) => f.endsWith(".html")).sort()) {
  const source = readFileSync(join(pagesDir, file), "utf8");
  const match = source.match(/^<!--page\s+(\{[\s\S]*?\})\s*-->\n?/);
  if (!match) throw new Error(`${file}: missing <!--page {...} --> header`);
  const slug = file.replace(/\.html$/, "");
  const url = slug === "index" ? "/" : slug === "404" ? "/404.html" : `/${slug}/`;
  const out = slug === "index" || slug === "404" ? `${slug}.html` : `${slug}/index.html`;
  const meta = JSON.parse(match[1].replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, path) => lookup(path, config)));
  const page = { ...meta, url, slug };
  // A page can set "fullTitle" to replace the default "Title · Mile Zero".
  page.fullTitle ??= `${page.title} · ${config.brand.name}`;

  page.body = render(source.slice(match[0].length), page);
  outputs.set(out, render(readFileSync(join(root, "src/partials/layout.html"), "utf8"), page));
  if (slug !== "404") indexed.push(url);
}

// Home first, then the rest in alphabetical order.
indexed.sort((a, b) => (a === "/" ? -1 : b === "/" ? 1 : a.localeCompare(b)));
outputs.set(
  "sitemap.xml",
  `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${indexed.map((u) => `  <url><loc>${siteUrl}${u}</loc></url>`).join("\n")}
</urlset>
`
);
outputs.set("robots.txt", `User-agent: *\nAllow: /\n\nSitemap: ${siteUrl}/sitemap.xml\n`);

let stale = 0;
for (const [out, content] of outputs) {
  const target = join(root, out);
  if (check) {
    if (!existsSync(target) || readFileSync(target, "utf8") !== content) {
      console.error(`stale: ${relative(root, target)}`);
      stale++;
    }
  } else {
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, content);
    console.log(`built ${out}`);
  }
}

if (check && stale) {
  console.error(`\n${stale} file(s) out of date. Run: node scripts/build.mjs`);
  process.exit(1);
}
